@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Nike DNA — athletic black/white, condensed uppercase display, volt accent */
.theme-nike-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.970 0 0);
  --surface-2: oklch(0.925 0 0);
  --fg: oklch(0.178 0 0);
  --fg-muted: oklch(0.546 0.003 286.3);
  --accent: oklch(0.178 0 0);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.925 0.230 120.5); /* volt */
  --line: oklch(0.85 0 0);
  --success: oklch(0.675 0.179 147.6);
  --warning: oklch(0.803 0.162 74.7);
  --danger: oklch(0.58 0.22 27);

  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;

  --shadow-1: none;
  --shadow-2: 0 10px 30px -14px oklch(0 0 0 / 40%);
  --shadow-3: 0 24px 60px -24px oklch(0 0 0 / 55%);
  --glow: 0 0 0 3px var(--accent);

  --border-width: 2px;
  --blur-amount: 0px;

  --font-display: "Oswald", "Arial Narrow", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: 0.005em;
  --label-transform: uppercase;
  --label-tracking: 0.12em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-nike-dna h1,
.theme-nike-dna h2,
.theme-nike-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  text-transform: uppercase;
  font-weight: 400;
  line-height: 0.9;
}

.theme-nike-dna h1 {
  font-size: clamp(3.5rem, 10vw, 8rem);
}

.theme-nike-dna button {
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 700;
  border-radius: var(--radius-pill);
}

/* signature */
.theme-nike-dna { --font-ui: var(--font-display); }
.theme-nike-dna button { text-transform: uppercase; font-weight: 600; letter-spacing: 0.02em; }
.theme-nike-dna h1 { text-transform: uppercase; font-style: italic; }
.theme-nike-dna h2 { text-transform: uppercase; }

/* depth */
.theme-nike-dna ::selection { background: var(--accent-2); color: oklch(0.13 0 0); }
.theme-nike-dna thead th { font-family: var(--font-display); text-transform: uppercase; letter-spacing: 0.1em; font-weight: 500; background: var(--accent); color: var(--accent-fg); border-bottom: none; }
.theme-nike-dna td { border-bottom: 1px solid var(--line); }
.theme-nike-dna tbody tr:hover { background: color-mix(in oklab, var(--accent-2) 14%, transparent); }
.theme-nike-dna a { color: var(--fg); font-weight: 600; text-decoration: none; background-image: linear-gradient(var(--accent-2), var(--accent-2)); background-size: 100% 0.3em; background-position: 0 92%; background-repeat: no-repeat; transition: background-size 120ms ease; }
.theme-nike-dna a:hover { background-size: 100% 100%; }
.theme-nike-dna input, .theme-nike-dna select, .theme-nike-dna textarea { border: var(--border-width) solid var(--fg); border-radius: var(--radius-pill); background: var(--bg); }
.theme-nike-dna textarea { border-radius: var(--radius); }
.theme-nike-dna input:focus-visible, .theme-nike-dna select:focus-visible, .theme-nike-dna textarea:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-2); }
.theme-nike-dna kbd { font-family: var(--font-display); text-transform: uppercase; background: var(--accent); color: var(--accent-fg); border-radius: var(--radius-pill); padding: 0.1em 0.55em; border: none; }
.theme-nike-dna .label-caps { font-family: var(--font-display); font-weight: 500; }
.theme-nike-dna .themed-border { border-left: 4px solid var(--accent-2); }
.theme-nike-dna button { transition: transform 100ms ease; }
.theme-nike-dna button:hover { transform: skewX(-6deg); }
.theme-nike-dna button:active { transform: skewX(-6deg) scale(0.97); }
.theme-nike-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-nike-dna ::-webkit-scrollbar-track { background: var(--surface); }
.theme-nike-dna ::-webkit-scrollbar-thumb { background: var(--fg); border-radius: 9999px; }
.theme-nike-dna ::-webkit-scrollbar-thumb:hover { background: var(--accent-2); }

/* alt mode: volt night — black court, volt everything */
.theme-nike-dna.alt-mode {
  --bg: oklch(0.145 0.000 0.0);
  --surface: oklch(0.185 0.000 0.0);
  --surface-2: oklch(0.225 0.000 0.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --accent: oklch(0.925 0.230 120.5);
  --accent-fg: oklch(0.13 0 0);
  --accent-2: oklch(0.925 0.230 120.5);
  --glow: 0 0 0 3px var(--accent);
}
.theme-nike-dna.alt-mode thead th { background: var(--accent); color: var(--accent-fg); }
.theme-nike-dna.alt-mode a { color: var(--fg); }
.theme-nike-dna.alt-mode a:hover { color: oklch(0.13 0 0); }
.theme-nike-dna.alt-mode input, .theme-nike-dna.alt-mode select, .theme-nike-dna.alt-mode textarea { border-color: var(--fg); background: var(--surface); }
.theme-nike-dna.alt-mode ::-webkit-scrollbar-thumb { background: var(--accent); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"], [class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
